package com.yuegang.zhihui.order.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.order.api.*;import java.math.*;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;
public final class OrderService{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public OrderService(DataSource d){jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}public OrderView create(long user,CreateOrderRequest c){return tx.execute(s->{OrderView existing=findByRequest(user,c.requestId());if(existing!=null)return existing;String currency=null;BigDecimal total=BigDecimal.ZERO;for(var i:c.items()){if(currency==null)currency="CNY";total=total.add(i.unitPrice().multiply(BigDecimal.valueOf(i.quantity())));}long id=next();String no="YG"+Long.toUnsignedString(id);jdbc.update("INSERT INTO order_main(id,order_no,request_id,user_id,status,total_amount,currency,remark,expires_at) VALUES(?,?,?,?, 'PENDING_PAYMENT',?,?,?,DATE_ADD(NOW(6),INTERVAL 30 MINUTE))",id,no,c.requestId(),user,total,currency,c.remark());for(var i:c.items()){BigDecimal sub=i.unitPrice().multiply(BigDecimal.valueOf(i.quantity()));jdbc.update("INSERT INTO order_item(id,order_id,sku_id,sku_code,product_name,unit_price,quantity,subtotal,product_snapshot) VALUES(?,?,?,?,?,?,?,?,JSON_OBJECT('skuId',?,'skuCode',?,'name',?,'unitPrice',?))",next(),id,id(i.skuId()),i.skuCode(),i.productName(),i.unitPrice(),i.quantity(),sub,i.skuId(),i.skuCode(),i.productName(),i.unitPrice());}var a=c.address();jdbc.update("INSERT INTO order_address_snapshot(order_id,recipient_name,recipient_phone,country_code,province_code,province_name,city_name,district_name,address_detail,postal_code) VALUES(?,?,?,?,?,?,?,?,?,?)",id,a.recipientName(),a.recipientPhone(),a.countryCode(),a.provinceCode(),a.provinceName(),a.cityName(),a.districtName(),a.addressDetail(),a.postalCode());clearOrderedCartItems(user,c.items());history(id,null,"PENDING_PAYMENT",null,"ORDER_CREATED");outbox(id,"ORDER_CREATED",UUID.randomUUID().toString());return get(user,Long.toString(id));});}public OrderView get(long user,String order){return jdbc.query("SELECT id,order_no,user_id,status,total_amount,currency,version,created_at FROM order_main WHERE id=? AND user_id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return view(r);},id(order),user);}public OrderView cancel(long user,String order,long version){return transition(user,order,version,"PENDING_PAYMENT","CANCELLED","USER_CANCELLED","ORDER_CANCELLED");}public OrderView requestRefund(long user,String order,long version){return transition(user,order,version,"PAID","REFUNDING","USER_REFUND_REQUESTED","ORDER_REFUND_REQUESTED");}public OrderView startProcessing(long user,String order,long version){return transition(user,order,version,"PAID","PROCESSING","SIMULATED_FULFILLMENT_STARTED","ORDER_PROCESSING");}public OrderView complete(long user,String order,long version){return transition(user,order,version,"PROCESSING","COMPLETED","SIMULATED_FULFILLMENT_COMPLETED","ORDER_COMPLETED");}public int closeExpired(){return tx.execute(s->{var ids=jdbc.queryForList("SELECT id FROM order_main WHERE status='PENDING_PAYMENT' AND expires_at<NOW(6) FOR UPDATE",Long.class);for(long id:ids){jdbc.update("UPDATE order_main SET status='CLOSED',version=version+1 WHERE id=? AND status='PENDING_PAYMENT'",id);history(id,"PENDING_PAYMENT","CLOSED",null,"PAYMENT_TIMEOUT");outbox(id,"ORDER_CLOSED",UUID.randomUUID().toString());}return ids.size();});}private OrderView transition(long user,String order,long version,String from,String to,String reason,String event){return tx.execute(s->{long id=id(order);int n=jdbc.update("UPDATE order_main SET status=?,cancelled_at=CASE WHEN ?='CANCELLED' THEN NOW(6) ELSE cancelled_at END,version=version+1 WHERE id=? AND user_id=? AND version=? AND status=?",to,to,id,user,version,from);if(n!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);history(id,from,to,null,reason);outbox(id,event,UUID.randomUUID().toString());return get(user,order);});}public void paymentSucceeded(String eventId,String orderId){eventTransition(eventId,"WALLET_PAYMENT_SUCCEEDED",orderId,"PENDING_PAYMENT","PAID","PAYMENT_SUCCEEDED","ORDER_PAID");}public void refundSucceeded(String eventId,String orderId){eventTransition(eventId,"WALLET_REFUND_SUCCEEDED",orderId,"REFUNDING","REFUNDED","REFUND_SUCCEEDED","ORDER_REFUNDED");}private void eventTransition(String eventId,String eventType,String orderId,String from,String to,String reason,String outgoing){tx.executeWithoutResult(s->{if(jdbc.update("INSERT IGNORE INTO order_inbox(event_id,event_type) VALUES(?,?)",eventId,eventType)==0)return;long id=id(orderId);int n=jdbc.update("UPDATE order_main SET status=?,paid_at=CASE WHEN ?='PAID' THEN NOW(6) ELSE paid_at END,version=version+1 WHERE id=? AND status=?",to,to,id,from);if(n==1){history(id,from,to,eventId,reason);outbox(id,outgoing,UUID.randomUUID().toString());}});}private OrderView findByRequest(long u,String r){return jdbc.query("SELECT id,order_no,user_id,status,total_amount,currency,version,created_at FROM order_main WHERE user_id=? AND request_id=?",x->x.next()?view(x):null,u,r);}private void clearOrderedCartItems(long user,List<OrderItemCommand>items){for(var item:items)jdbc.update("DELETE FROM order_cart_item WHERE user_id=? AND sku_id=?",user,id(item.skuId()));}private static OrderView view(java.sql.ResultSet r)throws java.sql.SQLException{return new OrderView(Long.toString(r.getLong(1)),r.getString(2),Long.toString(r.getLong(3)),OrderStatus.valueOf(r.getString(4)),r.getBigDecimal(5),r.getString(6),r.getLong(7),r.getTimestamp(8).toLocalDateTime().atOffset(ZoneOffset.UTC));}private void history(long o,String f,String t,String e,String reason){jdbc.update("INSERT INTO order_state_history(id,order_id,from_status,to_status,event_id,reason) VALUES(?,?,?,?,?,?)",next(),o,f,t,e,reason);}private void outbox(long o,String t,String e){jdbc.update("INSERT INTO order_outbox(id,aggregate_id,event_type,payload_json) VALUES(?,?,?,JSON_OBJECT('eventId',?,'orderId',?))",e,Long.toString(o),t,e,Long.toString(o));}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}private static long id(String s){try{long v=Long.parseLong(s);if(v<=0)throw new NumberFormatException();return v;}catch(NumberFormatException e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
